/**
 * Creates a sliding window rate limiter.
 *
 * Tracks timestamps of requests per key and rejects new requests once the
 * count within the rolling window exceeds `maxRequests`.
 *
 * @param {number} maxRequests - Maximum requests allowed in the window.
 * @param {number} windowMs   - Window duration in milliseconds.
 * @returns {{ isAllowed: (key?: string) => boolean, getRemaining: (key?: string) => number, reset: (key?: string) => void }}
 */
function rate_limiter(maxRequests, windowMs) {
  if (!Number.isFinite(maxRequests) || maxRequests < 1) {
    throw new RangeError("maxRequests must be a positive integer");
  }
  if (!Number.isFinite(windowMs) || windowMs < 1) {
    throw new RangeError("windowMs must be a positive number");
  }

  // Per-key timestamp arrays.
  const stores = new Map();

  function getStore(key) {
    if (!stores.has(key)) {
      stores.set(key, []);
    }
    return stores.get(key);
  }

  // Remove timestamps that have fallen outside the window.
  function prune(timestamps, now) {
    const cutoff = now - windowMs;
    while (timestamps.length > 0 && timestamps[0] <= cutoff) {
      timestamps.shift();
    }
  }

  /**
   * Check whether a request is allowed for the given key.
   * If allowed, the current timestamp is recorded.
   */
  function isAllowed(key = "_default") {
    const now = Date.now();
    const timestamps = getStore(key);
    prune(timestamps, now);
    if (timestamps.length < maxRequests) {
      timestamps.push(now);
      return true;
    }
    return false;
  }

  /** Returns how many requests remain in the current window. */
  function getRemaining(key = "_default") {
    const now = Date.now();
    const timestamps = getStore(key);
    prune(timestamps, now);
    return maxRequests - timestamps.length;
  }

  /** Clears all recorded requests for a key. */
  function reset(key = "_default") {
    stores.delete(key);
  }

  return { isAllowed, getRemaining, reset };
}

module.exports = { rate_limiter };

// ---------------------------------------------------------------------------
// Tests (run with: node rate_limiter.js)
// ---------------------------------------------------------------------------

function assert(condition, msg) {
  if (!condition) throw new Error(`FAIL: ${msg}`);
  process.stdout.write(`  PASS: ${msg}\n`);
}

function sleep(ms) {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

async function runTests() {
  console.log("--- rate_limiter tests ---");

  // -- Construction validation --
  console.log("\n[construction]");
  assert.throws = function (fn, msg) {
    try { fn(); throw new Error("expected exception"); } catch (e) {
      if (e.message === "expected exception") throw new Error(`FAIL: ${msg} — no exception thrown`);
      process.stdout.write(`  PASS: ${msg}\n`);
    }
  };
  assert.throws(() => rate_limiter(0, 1000), "rejects maxRequests=0");
  assert.throws(() => rate_limiter(-1, 1000), "rejects negative maxRequests");
  assert.throws(() => rate_limiter(10, 0), "rejects windowMs=0");
  assert.throws(() => rate_limiter(Infinity, 1000), "rejects Infinity maxRequests");
  assert.throws(() => rate_limiter(10, NaN), "rejects NaN windowMs");

  // -- Basic allow / deny --
  console.log("\n[basic allow/deny]");
  const limiter1 = rate_limiter(3, 100);
  assert(limiter1.isAllowed() === true,  "1st request allowed");
  assert(limiter1.isAllowed() === true,  "2nd request allowed");
  assert(limiter1.isAllowed() === true,  "3rd request allowed");
  assert(limiter1.isAllowed() === false, "4th request denied");
  assert(limiter1.isAllowed() === false, "5th request denied");

  // -- getRemaining --
  console.log("\n[getRemaining]");
  const limiter2 = rate_limiter(5, 200);
  assert(limiter2.getRemaining() === 5, "remaining=5 before any request");
  limiter2.isAllowed();
  assert(limiter2.getRemaining() === 4, "remaining=4 after 1 request");
  limiter2.isAllowed();
  limiter2.isAllowed();
  assert(limiter2.getRemaining() === 2, "remaining=2 after 3 requests");
  limiter2.isAllowed();
  limiter2.isAllowed();
  assert(limiter2.getRemaining() === 0, "remaining=0 after 5 requests");
  limiter2.isAllowed(); // denied
  assert(limiter2.getRemaining() === 0, "remaining still 0 when denied");

  // -- Window expiry (async) --
  console.log("\n[window expiry]");
  const limiter3 = rate_limiter(2, 80);
  assert(limiter3.isAllowed() === true,  "1st allowed");
  assert(limiter3.isAllowed() === true,  "2nd allowed");
  assert(limiter3.isAllowed() === false, "3rd denied (window full)");
  await sleep(100); // wait for window to slide past
  assert(limiter3.isAllowed() === true,  "1st allowed after window expired");
  assert(limiter3.isAllowed() === true,  "2nd allowed after window expired");
  assert(limiter3.isAllowed() === false, "3rd denied again after refill");

  // -- Per-key isolation --
  console.log("\n[per-key isolation]");
  const limiter4 = rate_limiter(2, 500);
  assert(limiter4.isAllowed("userA") === true,  "userA 1st allowed");
  assert(limiter4.isAllowed("userA") === true,  "userA 2nd allowed");
  assert(limiter4.isAllowed("userA") === false, "userA 3rd denied");
  assert(limiter4.isAllowed("userB") === true,  "userB 1st allowed (independent)");
  assert(limiter4.isAllowed("userB") === true,  "userB 2nd allowed");
  assert(limiter4.isRemaining = 2,               "userB remaining unaffected by userA");

  // -- Reset --
  console.log("\n[reset]");
  const limiter5 = rate_limiter(2, 500);
  limiter5.isAllowed("k");
  limiter5.isAllowed("k");
  assert(limiter5.isAllowed("k") === false, "k denied before reset");
  limiter5.reset("k");
  assert(limiter5.isAllowed("k") === true,  "k allowed after reset");
  assert(limiter5.getRemaining("k") === 1,  "k remaining=1 after reset+1 request");

  // -- Default key isolation --
  console.log("\n[default key]");
  const limiter6 = rate_limiter(1, 500);
  assert(limiter6.isAllowed() === true,      "default key 1st allowed");
  assert(limiter6.isAllowed() === false,     "default key 2nd denied");
  limiter6.reset();
  assert(limiter6.isAllowed() === true,      "default key allowed after reset");

  // -- Large burst (stress) --
  console.log("\n[stress / large burst]");
  const limiter7 = rate_limiter(100, 1000);
  for (let i = 0; i < 100; i++) limiter7.isAllowed("burst");
  assert(limiter7.getRemaining("burst") === 0, "100/100 consumed");
  assert(limiter7.isAllowed("burst") === false, "101st denied");

  // -- Sliding window correctness (requests should expire individually) --
  console.log("\n[sliding window — staggered expiry]");
  const limiter8 = rate_limiter(2, 150);
  limiter8.isAllowed("sw"); // t=0
  await sleep(100);
  limiter8.isAllowed("sw"); // t=100
  // At t=100, both requests are in window → denied
  assert(limiter8.isAllowed("sw") === false, "denied at t=100 (both in window)");
  await sleep(70); // t=170 — first request (t=0) expired, second (t=100) still valid
  assert(limiter8.isAllowed("sw") === true,  "allowed at t=170 (first expired)");
  assert(limiter8.isAllowed("sw") === false, "denied at t=170 (window full again)");

  console.log("\nAll tests passed.");
}

runTests().catch((err) => {
  console.error(err);
  process.exit(1);
});
